import {breakdown,credited,total,paid,balance,lineTotal,dateOK} from './core.js';
const money=n=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR',minimumFractionDigits:2}).format(n/100);
const date=s=>dateOK(s)?new Date(s+'T12:00:00Z').toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'}):'—';
export async function invoicePDF(invoice,{fontBytes}={}){
 const {PDFDocument,rgb}=await import('./vendor/pdf-lib.js');await import('./vendor/fontkit.js');
 if(!fontBytes){const response=await fetch(new URL('./vendor/DejaVuSans.ttf',import.meta.url));if(!response.ok)throw Error('Could not load the invoice font. Use Print / save PDF, or reconnect and try again.');fontBytes=new Uint8Array(await response.arrayBuffer())}
 const doc=await PDFDocument.create();doc.registerFontkit(globalThis.fontkit);const font=await doc.embedFont(fontBytes,{subset:true});const supported=new Set(font.getCharacterSet());
 const width=595.28,height=841.89,margin=42,right=width-margin,bottom=64;let page,y;const pages=[];
 const ink=rgb(.11,.18,.15),muted=rgb(.36,.43,.39),green=invoice.template==='minimal'?rgb(.12,.12,.12):invoice.template==='bold'?rgb(.12,.22,.48):rgb(.094,.306,.263),pale=rgb(.94,.96,.94);
 function text(value,x,yy,size=10,color=ink){value=String(value??'').replace(/\t/g,'    ');for(const ch of value){if(ch==='\n'||ch==='\r')continue;if(!supported.has(ch.codePointAt(0)))throw Error('This invoice contains a character the PDF font cannot display. Use Print / save PDF to preserve your text.')}page.drawText(value,{x,y:yy,size,font,color})}
 function rule(yy){page.drawLine({start:{x:margin,y:yy},end:{x:right,y:yy},thickness:.6,color:rgb(.83,.87,.83)})}
 function newPage(){page=doc.addPage([width,height]);pages.push(page);y=height-45;if(pages.length>1){text(`${invoice.number} · continued`,margin,y,10,green);y-=28}}
 function ensure(space){if(y-space<bottom)newPage()}
 function wrap(value,maxWidth,size=10){const output=[];for(const para of String(value??'').replace(/\r/g,'').split('\n')){if(!para){output.push('');continue}let line='';for(const word of para.split(/\s+/)){let trial=line?line+' '+word:word;if(font.widthOfTextAtSize(trial,size)<=maxWidth){line=trial;continue}if(line){output.push(line);line=''}let chunk='';for(const ch of word){if(font.widthOfTextAtSize(chunk+ch,size)>maxWidth&&chunk){output.push(chunk);chunk=''}chunk+=ch}line=chunk}output.push(line)}return output}
 function paragraph(value,{x=margin,maxWidth=right-margin,size=10,color=ink,gap=5}={}){const lines=wrap(value,maxWidth,size);for(const line of lines){ensure(size+6);text(line,x,y,size,color);y-=size+5}y-=gap}
 function label(value){ensure(32);text(value,margin,y,8,muted);y-=18}
 function amount(label,value,{strong=false}={}){ensure(28);text(label,margin,y,strong?12:10,strong?green:muted);const v=money(value);text(v,right-font.widthOfTextAtSize(v,strong?14:11),y,strong?14:11,strong?green:ink);y-=25}
 const labelText=invoice.kind==='quote'?'QUOTE':invoice.kind==='credit'?'CREDIT NOTE':invoice.kind==='receipt'?'PAYMENT RECEIPT':invoice.business.nonVat===false?'TAX INVOICE':'INVOICE';newPage();text((invoice.state==='draft'?'DRAFT ':'')+(invoice.state==='void'?'VOID ':'')+labelText,margin,y,23,green);y-=30;text(invoice.number,margin,y,11);y-=32;
 paragraph(invoice.business.name,{size:13,color:green});paragraph([invoice.business.address,invoice.business.email,invoice.business.phone,invoice.business.vatNumber?`VAT: ${invoice.business.vatNumber}`:null].filter(Boolean).join('\n'),{size:10,color:muted,gap:10});rule(y);y-=24;
 label('BILL TO');paragraph(invoice.customer.name,{size:12});paragraph([invoice.customer.address,invoice.customer.email,invoice.customer.vatNumber?`VAT: ${invoice.customer.vatNumber}`:null].filter(Boolean).join('\n'),{color:muted});paragraph(`${invoice.kind==='quote'?'Quote date':'Invoice date'}: ${date(invoice.date)}     ${invoice.kind==='quote'?'Valid until':'Due date'}: ${date(invoice.due)}`,{gap:12});
 function tableHeader(){ensure(55);page.drawRectangle({x:margin,y:y-9,width:right-margin,height:25,color:pale});text('DESCRIPTION',margin+8,y,8,muted);text('QTY',305,y,8,muted);text('UNIT PRICE',365,y,8,muted);text('AMOUNT',485,y,8,muted);y-=30}
 tableHeader();
 for(const line of invoice.lines){const lines=wrap(line.description,240,9),rowHeight=Math.max(30,lines.length*14+12);if(y-rowHeight<bottom&&rowHeight<height-140){newPage();tableHeader()}let first=true;for(const l of lines){if(y-18<bottom){newPage();tableHeader();if(!first){text('(continued)',305,y,8,muted)}}text(l,margin+8,y,9);if(first){text(String(line.quantity/100),305,y,9);const p=money(line.price),a=money(lineTotal(line));text(p,450-font.widthOfTextAtSize(p,9),y,9);text(a,right-8-font.widthOfTextAtSize(a,9),y,9);first=false}y-=14}y-=10;rule(y);y-=12}
 ensure(200);y-=10;const b=breakdown(invoice);amount('Subtotal',b.subtotal);if(b.discount)amount('Discount',-b.discount);amount('Value excluding VAT',b.net);amount(`VAT ${(invoice.vatRate||0)/100}%`,b.vat);amount(invoice.kind==='quote'?'Quote total':'Document total',total(invoice));if(credited(invoice))amount('Credit notes',credited(invoice));if(invoice.kind!=='quote'&&invoice.kind!=='credit')amount('Payments recorded',paid(invoice));rule(y+20);amount(invoice.kind==='credit'?'Credit value':invoice.kind==='quote'?'Quoted total':invoice.kind==='receipt'?'Balance remaining':invoice.state==='void'?'Amount due · voided':'Amount due',invoice.state==='void'?0:balance(invoice),{strong:true});y-=12;
 if(invoice.deposit)paragraph(`Requested deposit: ${money(invoice.deposit)} (included in total; not a recorded payment).`,{size:9,color:muted});if(invoice.paymentLink)paragraph('Payment link: '+invoice.paymentLink,{size:9,color:muted});if(invoice.business.bank){label('PAYMENT INSTRUCTIONS');paragraph(invoice.business.bank,{color:muted});paragraph('Reference: '+invoice.number,{color:muted,gap:12})}
 if(invoice.notes){label('NOTE');paragraph(invoice.notes,{color:muted,gap:12})}
 const active=invoice.payments.filter(p=>!p.reversed);if(active.length){label('PAYMENTS RECORDED');for(const p of active){paragraph(`${date(p.date)} · ${money(p.amount)} · ${p.reference||'Payment'}`,{size:9,color:muted})}}
 paragraph(invoice.business.nonVat===false?`VAT treatment: ${invoice.taxMode||'none'}; rate ${(invoice.vatRate||0)/100}%.`:'VAT is not charged. Supplier is not VAT registered.',{size:9,color:muted});if(invoice.state==='draft')paragraph('Draft only - not yet issued.',{size:9,color:muted});if(invoice.state==='void')paragraph('This invoice has been voided.',{size:9,color:muted});
 for(let n=0;n<pages.length;n++){page=pages[n];text('InvoiceFlow · '+invoice.number,margin,32,8,muted);const footer=`Page ${n+1} of ${pages.length}`;text(footer,right-font.widthOfTextAtSize(footer,8),32,8,muted)}
 doc.setTitle(`${invoice.number} - ${invoice.customer.name}`);doc.setAuthor(invoice.business.name);doc.setCreator('InvoiceFlow');doc.setSubject(`${labelText} in South African rand. ${invoice.business.nonVat?'Supplier not VAT registered.':'VAT registration: '+invoice.business.vatNumber}`);return doc.save();
}
